const fs = require('fs');
const p = '/workspace/.devcontainer/keycloak/imports/startuphafen.json';
const d = JSON.parse(fs.readFileSync(p,'utf8'));
console.log('before:', d.passwordPolicy);
// The dev realm documents passwords 'admin'/'alice'/'marie' (README Dev Logins).
// KC 26 validates imported credentials against the realm password policy and
// fails the whole import otherwise. Relax the dev policy so the documented
// dev credentials can be imported unchanged.
d.passwordPolicy = 'length(5)';
fs.writeFileSync(p, JSON.stringify(d, null, 2));
const d2 = JSON.parse(fs.readFileSync(p,'utf8'));
console.log('after:', d2.passwordPolicy);
console.log('users still:', d2.users.map(u=>u.username+':'+u.credentials[0].value));
